**Example 1 — Basic Custom Exception**
```python
# ─── Simple custom exception ───
class ValidationError(Exception):
    """Raised when input validation fails"""
    pass

class DatabaseError(Exception):
    """Raised for database operation failures"""
    pass

class NotFoundError(Exception):
    """Raised when a requested resource doesn't exist"""
    pass

# Usage
def get_user(user_id: int):
    if not isinstance(user_id, int):
        raise TypeError(f"user_id must be int, got {type(user_id).__name__}")
    if user_id <= 0:
        raise ValidationError(f"user_id must be positive, got {user_id}")
    if user_id > 1000:
        raise NotFoundError(f"User {user_id} not found")
    return {"id": user_id, "name": "Alice"}

try:
    user = get_user(-1)
except ValidationError as e:
    print(f"Validation: {e}")
except NotFoundError as e:
    print(f"Not found: {e}")
```

**Example 2 — Rich Custom Exceptions with Extra Data**
```python
from dataclasses import dataclass, field
from typing import Any, Optional, List
from datetime import datetime

class AppError(Exception):
    """Base exception for all application errors"""

    def __init__(
        self,
        message: str,
        code: str = "UNKNOWN_ERROR",
        details: Optional[dict] = None,
        retry_after: Optional[int] = None  # seconds
    ):
        super().__init__(message)
        self.message = message
        self.code = code
        self.details = details or {}
        self.retry_after = retry_after
        self.timestamp = datetime.now().isoformat()

    def to_dict(self) -> dict:
        """Convert to dict for API response"""
        result = {
            "error": True,
            "code": self.code,
            "message": self.message,
            "timestamp": self.timestamp,
        }
        if self.details:
            result["details"] = self.details
        if self.retry_after:
            result["retry_after"] = self.retry_after
        return result

    def __repr__(self):
        return f"{type(self).__name__}(code={self.code!r}, message={self.message!r})"

class ValidationError(AppError):
    """Input validation failure"""

    def __init__(self, message: str, field: str = None, value: Any = None):
        super().__init__(
            message=message,
            code="VALIDATION_ERROR",
            details={"field": field, "value": str(value) if value is not None else None}
        )
        self.field = field
        self.value = value

class RateLimitError(AppError):
    """Rate limit exceeded"""

    def __init__(self, limit: int, window: int, retry_after: int):
        super().__init__(
            message=f"Rate limit of {limit} requests per {window}s exceeded",
            code="RATE_LIMIT_EXCEEDED",
            details={"limit": limit, "window_seconds": window},
            retry_after=retry_after
        )

class AuthenticationError(AppError):
    """Authentication failure"""

    def __init__(self, reason: str = "Invalid credentials"):
        super().__init__(
            message=reason,
            code="AUTH_FAILED"
        )

# ─── Usage ───
def register_user(data: dict):
    if not data.get("email"):
        raise ValidationError("Email is required", field="email")

    if "@" not in data.get("email", ""):
        raise ValidationError("Invalid email format", field="email", value=data["email"])

    if len(data.get("password", "")) < 8:
        raise ValidationError("Password too short (min 8 chars)", field="password")

    return {"user_id": 42, "email": data["email"]}

try:
    user = register_user({"email": "not-an-email", "password": "123"})
except ValidationError as e:
    print(e.to_dict())
    # {'error': True, 'code': 'VALIDATION_ERROR',
    #  'message': 'Invalid email format',
    #  'details': {'field': 'email', 'value': 'not-an-email'}, ...}
except AppError as e:
    print(f"App error: {e}")  # Catch-all for our custom hierarchy
```

**Example 3 — Exception Hierarchy for a Domain**
```python
# ─── Build a complete exception hierarchy ───
# Base
class APIError(Exception):
    status_code: int = 500
    error_code: str = "API_ERROR"

    def __init__(self, message: str, **kwargs):
        super().__init__(message)
        for k, v in kwargs.items():
            setattr(self, k, v)

# 4xx Client Errors
class ClientError(APIError):
    status_code = 400

class BadRequestError(ClientError):
    status_code = 400
    error_code = "BAD_REQUEST"

class UnauthorizedError(ClientError):
    status_code = 401
    error_code = "UNAUTHORIZED"

class ForbiddenError(ClientError):
    status_code = 403
    error_code = "FORBIDDEN"

class NotFoundError(ClientError):
    status_code = 404
    error_code = "NOT_FOUND"

class ConflictError(ClientError):
    status_code = 409
    error_code = "CONFLICT"

class UnprocessableError(ClientError):
    status_code = 422
    error_code = "UNPROCESSABLE"

# 5xx Server Errors
class ServerError(APIError):
    status_code = 500

class DatabaseError(ServerError):
    status_code = 500
    error_code = "DB_ERROR"

class ExternalServiceError(ServerError):
    status_code = 502
    error_code = "EXTERNAL_SERVICE_ERROR"

class ServiceUnavailableError(ServerError):
    status_code = 503
    error_code = "SERVICE_UNAVAILABLE"

# ─── Usage in FastAPI-style handler ───
def handle_exception(error: Exception) -> dict:
    """Convert any exception to an API response dict"""
    if isinstance(error, ClientError):
        return {
            "status_code": error.status_code,
            "body": {"error": error.error_code, "message": str(error)}
        }
    elif isinstance(error, ServerError):
        # Log server errors
        import logging
        logging.exception("Server error")
        return {
            "status_code": error.status_code,
            "body": {"error": error.error_code, "message": "Internal server error"}
        }
    else:
        return {
            "status_code": 500,
            "body": {"error": "UNKNOWN", "message": "An unexpected error occurred"}
        }

# Callers can catch at any level of the hierarchy:
try:
    raise NotFoundError("User 42 not found")
except NotFoundError:        # Specific ✅
    pass
except ClientError:          # Broader ✅
    pass
except APIError:             # Broadest custom ✅
    pass
```
